CREATE OR REPLACE PROCEDURE sp(
    para_flow_degradation_threshold NUMBER,
    para_eer_degradation_ratio      NUMBER,
    para_outdoor_heat_threshold     NUMBER
) IS
    v_next_id         NUMBER;
    v_emission_factor NUMBER;
    v_cooling_kw      NUMBER;
    v_heating_kw      NUMBER;
    v_pre_total       NUMBER;
    v_post_total      NUMBER;
    v_usage_hours     NUMBER;
    v_indoor_avg      NUMBER;
    v_outdoor_avg     NUMBER;
    v_output          NUMBER;
    v_seasonal_eff    NUMBER;
    v_seasonal_eff2   NUMBER;
    v_avg_power       NUMBER;
    v_avg_power2      NUMBER;
    v_pc_heat         NUMBER;
    v_flow_rate       NUMBER;
    v_required_flow   NUMBER;
    v_carnot          NUMBER;

    TYPE t_energy_id IS TABLE OF energy_consumption.energy_id%TYPE;
    TYPE t_kwh        IS TABLE OF energy_consumption.energy_consumption_kwh%TYPE;
    v_ids  t_energy_id;
    v_kwhs t_kwh;

    CURSOR c_ac IS
        SELECT ac_id, cooling_capacity_btu, heating_capacity_btu,
               energy_efficiency_ratio, power_consumption_watts, refrigerant_type
        FROM air_conditioner_info
        ORDER BY ac_id
        FOR UPDATE;
BEGIN
    SELECT NVL(MAX(id), 0) + 1 INTO v_next_id FROM carbon_emissions;

    FOR rec IN c_ac LOOP
        v_cooling_kw := NVL(rec.cooling_capacity_btu, 0) / 3412.0;
        v_heating_kw := NVL(rec.heating_capacity_btu, 0) / 3412.0;

        SELECT NVL(SUM(energy_consumption_kwh), 0)
          INTO v_pre_total
          FROM energy_consumption
         WHERE ac_id = rec.ac_id;

        SELECT NVL(SUM(usage_duration_hours), 0)
          INTO v_usage_hours
          FROM usage_records
         WHERE ac_id = rec.ac_id;

        SELECT AVG(indoor_temperature_celsius), AVG(outdoor_temperature_celsius)
          INTO v_indoor_avg, v_outdoor_avg
          FROM usage_records
         WHERE ac_id = rec.ac_id;

        v_indoor_avg  := NVL(v_indoor_avg, 24.0);
        v_outdoor_avg := NVL(v_outdoor_avg, 30.0);

        SELECT NVL(SUM(CASE WHEN "mode" = 'Cooling'
                            THEN v_cooling_kw * usage_duration_hours
                            ELSE v_heating_kw * usage_duration_hours END), 0)
          INTO v_output
          FROM usage_records
         WHERE ac_id = rec.ac_id;

        IF v_pre_total > 0 THEN
            v_seasonal_eff := v_output / v_pre_total;
        ELSE
            v_seasonal_eff := rec.energy_efficiency_ratio;
        END IF;

        IF v_pre_total > 0 AND v_usage_hours > 0 THEN
            v_avg_power := v_pre_total / v_usage_hours;
        ELSE
            v_avg_power := rec.power_consumption_watts / 1000.0;
        END IF;

        IF v_outdoor_avg - v_indoor_avg > 0 THEN
            v_carnot := (v_indoor_avg + 273.15) / (v_outdoor_avg - v_indoor_avg);
            IF v_seasonal_eff > v_carnot THEN
                v_seasonal_eff := v_carnot;
            END IF;
        END IF;

        SELECT MAX(phase_change_heat_kj_per_kg)
          INTO v_pc_heat
          FROM refrigerant_properties
         WHERE refrigerant_type = rec.refrigerant_type;
        v_pc_heat := NVL(v_pc_heat, 200);

        SELECT AVG(refrigerant_flow_rate_kg_per_s)
          INTO v_flow_rate
          FROM refrigerant_properties
         WHERE refrigerant_type = rec.refrigerant_type;
        IF v_flow_rate IS NULL THEN
            v_flow_rate := v_cooling_kw / 200;
        END IF;

        IF v_pc_heat <= 0 THEN
            CONTINUE;
        END IF;

        v_required_flow := v_cooling_kw / v_pc_heat;
        IF NOT (v_flow_rate < v_required_flow * para_flow_degradation_threshold) THEN
            CONTINUE;
        END IF;

        SELECT MAX(emission_factor)
          INTO v_emission_factor
          FROM carbon_emissions;
        IF v_emission_factor IS NULL THEN
            v_emission_factor := 0.5;
        END IF;

        SELECT energy_id, energy_consumption_kwh
          BULK COLLECT INTO v_ids, v_kwhs
          FROM energy_consumption
         WHERE ac_id = rec.ac_id
           AND power_consumption_watts > rec.power_consumption_watts * 1.15
           AND outdoor_temperature_celsius > para_outdoor_heat_threshold
         ORDER BY energy_id;

        FOR i IN 1 .. v_ids.COUNT LOOP
            DELETE FROM energy_consumption WHERE energy_id = v_ids(i);
        END LOOP;

        SELECT NVL(SUM(energy_consumption_kwh), 0)
          INTO v_post_total
          FROM energy_consumption
         WHERE ac_id = rec.ac_id;

        IF v_post_total > 0 THEN
            v_seasonal_eff2 := v_output / v_post_total;
        ELSE
            v_seasonal_eff2 := rec.energy_efficiency_ratio;
        END IF;

        IF v_post_total > 0 AND v_usage_hours > 0 THEN
            v_avg_power2 := v_post_total / v_usage_hours;
        ELSE
            v_avg_power2 := rec.power_consumption_watts / 1000.0;
        END IF;

        IF v_outdoor_avg - v_indoor_avg > 0 THEN
            v_carnot := (v_indoor_avg + 273.15) / (v_outdoor_avg - v_indoor_avg);
            IF v_seasonal_eff2 > v_carnot THEN
                v_seasonal_eff2 := v_carnot;
            END IF;
        END IF;

        IF v_seasonal_eff2 < rec.energy_efficiency_ratio * para_eer_degradation_ratio THEN
            UPDATE air_conditioner_info
               SET energy_efficiency_ratio = v_seasonal_eff2,
                   power_consumption_watts = v_avg_power2 * 1000.0
             WHERE ac_id = rec.ac_id;
        END IF;

        INSERT INTO carbon_emissions (id, emission_factor, annual_emissions_tonnes)
        VALUES (v_next_id, v_emission_factor, v_pre_total * v_emission_factor / 1000.0);
        v_next_id := v_next_id + 1;

        FOR i IN 1 .. v_ids.COUNT LOOP
            INSERT INTO carbon_emissions (id, emission_factor, annual_emissions_tonnes)
            VALUES (v_next_id, v_emission_factor,
                    NVL(v_kwhs(i), 0) * v_emission_factor / 1000.0);
            v_next_id := v_next_id + 1;
        END LOOP;
    END LOOP;
END sp;
